from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_autonomous_student_v432.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"),str(p),"exec")

def main():
    r=Path.cwd()
    req=[
      "alliance_autonomous_student_v431.py","alliance_autonomous_student_v430.py",
      "alliance_acquisition_intent_closure_v425.py","alliance_automation_grammar_rescue_v423.py",
      "alliance_automation_closure_v422.py","alliance_automation_truth_escalator_v421.py",
      "alliance_automation_machine_v420.py","alliance_cre_championship_v410.py",
      "alliance_cre_academy_v402.py","alliance_cre_academy_v401.py","alliance_cre_academy_v400.py",REG
    ]
    miss=[x for x in req if not (r/x).exists()]
    if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))

    v431=(r/"alliance_autonomous_student_v431.py").read_text(encoding="utf-8")
    needed=['VERSION = "4.3.1-ALLIANCE-AUTONOMOUS-STUDENT-V5-MASTERY-REPAIR"',
            "V431_TRAINING_HOLD_DO_NOT_FREEZE_V5",
            "V431_MIXED"]
    # Third marker may not exist in older text; verify exact known rules instead.
    if needed[0] not in v431 or needed[1] not in v431 or "V431_ALREADY_RENTED_CAPITAL_IS_SALE" not in v431:
        raise SystemExit("Current 4.3.1 source differs; refusing blind install.")

    reg=r/REG; old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v432-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)
    (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")

    marker="# FOUNDATION 4.3.2 - Alliance Autonomous Student Final Training Repair"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0: raise SystemExit("Registrar return not found; no changes made.")
        block=r"""
    # FOUNDATION 4.3.2 - Alliance Autonomous Student Final Training Repair
    # Additive only. V5 remains protected until cumulative training gates pass.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v432/status"):
            result["autonomous_v432"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v432","error":None}
        else:
            import alliance_autonomous_student_v432 as autonomous_v432
            result["autonomous_v432"] = {**autonomous_v432.register(core), "error": None}
    except Exception as exc:
        result["autonomous_v432"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v432","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")

    chk(r/MODULE); chk(reg)
    txt=reg.read_text(encoding="utf-8")
    checks={"v402":"academy_v402" in txt,"v410":"championship_v410" in txt,
             "v420":"automation_v420" in txt,"v421":"automation_v421" in txt,
             "v422":"automation_v422" in txt,"v423":"automation_v423" in txt,
             "v425":"automation_v425" in txt,"v430":"autonomous_v430" in txt,
             "v431":"autonomous_v431" in txt,"v432":"autonomous_v432" in txt}
    if not all(checks.values()): raise SystemExit("Cumulative verification failed: "+repr(checks))

    print("Alliance Autonomous Student 4.3.2 installed")
    print("Generic repairs: mixed parent final AMBIGUOUS precedence")
    print("and clause-local requirement transaction ownership")
    print("4.3.0 + 4.3.1 preserved")
    print("Fresh V5 freezes automatically only after cumulative PASS")
    print("Student excluded from V5 truth judges")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v432")
    print("Backup:",bak)

if __name__=="__main__":
    main()
